"""Misra-Gries heavy hitters in one pass with at most k-1 counters.

Guarantee: every stream element with true frequency > n/k MUST survive
pass one as a candidate (possibly undercounted by at most n/k).
"""

from collections import Counter


def heavy_hitters(stream, k):
    """One-pass Misra-Gries sketch.

    Maintains at most k-1 counters. Returns a dict {item: counter_value}
    of surviving candidates. Counter values may UNDERCOUNT the true
    frequency, but never by more than n/k; hence any item with true
    frequency > n/k is guaranteed to be present.
    """
    if k <= 0:
        raise ValueError("k must be positive")
    counters = {}
    for x in stream:
        if x in counters:
            counters[x] += 1
        elif len(counters) < k - 1:
            counters[x] = 1
        else:
            # Decrement every counter; drop those that hit zero.
            for key in list(counters):
                counters[key] -= 1
                if counters[key] == 0:
                    del counters[key]
    return counters


def exact_check(stream, k):
    """Second-pass filter: recount the surviving candidates exactly and
    keep only items whose true frequency exceeds n/k."""
    n = len(stream)
    threshold = n / k
    candidates = heavy_hitters(stream, k)
    counts = Counter(stream)
    return {x: counts[x] for x in candidates if counts[x] > threshold}

