def test_all_identical_stream():
    # k=1 -> 0 counters; no element can have freq > n, so {} is correct.
    assert heavy_hitters(["x"] * 1000, 1) == {}
    for k in (2, 5, 100):
        stream = ["x"] * 1000
        survivors = heavy_hitters(stream, k)
        assert survivors == {"x": 1000}

